from courier.cifrado import descifrar, huella
from courier.validators import normalizar_rut


def cifrar_conductores_existentes(apps, schema_editor):
    """Cifra el RUT y el teléfono de los conductores ya guardados y calcula la huella del RUT.

    Al leer, CampoCifrado devuelve tal cual los valores antiguos (sin cifrar);
    al guardar, los cifra.
    """
    Conductor = apps.get_model('courier', 'Conductor')
    for conductor in Conductor.objects.all():
        try:
            rut = normalizar_rut(conductor.rut)
        except ValidationError:
            rut = (conductor.rut or '').strip().upper()
        conductor.rut = rut
        conductor.rut_huella = huella(rut)
        conductor.save(update_fields=['rut', 'telefono', 'rut_huella'])


def descifrar_conductores(apps, schema_editor):
    """Reversa: deja el RUT y el teléfono otra vez en texto plano."""
    Conductor = apps.get_model('courier', 'Conductor')
    tabla = schema_editor.quote_name(Conductor._meta.db_table)
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(f'SELECT id, rut, telefono FROM {tabla}')
        for pk, rut, telefono in cursor.fetchall():
            cursor.execute(f'UPDATE {tabla} SET rut = %s, telefono = %s WHERE id = %s',
                           [descifrar(rut or ''), descifrar(telefono or ''), pk])


